func NewPoller(ctx context.Context, logger *zap.Logger, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	pollCtx, cancel := context.WithCancel(ctx)
	p := &Poller{logger: logger, interval: 30 * time.Second, update: update, ctx: pollCtx, cancel: cancel, done: make(chan struct{})}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll runs the configured update function until the poller's context is cancelled.
func (p *Poller) Poll() {
	p.mu.Lock()
	if p.started || p.closed {
		p.mu.Unlock()
		return
	}
	p.started = true
	p.mu.Unlock()
	defer close(p.done)
	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}
			if p.notify != nil {
				p.notify(modified)
			}
			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}
			p.logger.Debug("snapshot updated")
		}
	}
}

// Close cancels polling and waits for the polling loop to terminate.
func (p *Poller) Close() error {
	p.closeOnce.Do(func() {
		p.mu.Lock()
		p.closed = true
		started := p.started
		p.cancel()
		if !started {
			close(p.done)
		}
		p.mu.Unlock()
		<-p.done
	})
	return nil
}
